import {renderInsightCharts} from './charts.js?v=5';
import {createHoldRecorder,formatHeldTime} from './recorder.js?v=5';
import {STORAGE_KEY,SCHEMA_VERSION,createBurstSession,durationMs,TYPES,SEVERITIES,durationMinutes,formatDuration,validateEntry,parseBackup,mergeEntries,toCSV,summarise} from './model.js?v=5';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={book:'<path d="M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4zM14 7a3 3 0 0 1 3-3h4v14h-3a4 4 0 0 0-4 3"/>',chart:'<path d="M4 4v16h17M8 15v-4M13 15V6M18 15v-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-.6 3-2.5 1-2.5-1-2 3 2 2v3l-2 2 2 3 3-1 2 1 .6 3h4l.6-3 2-1 3 1 2-3-2-2v-3l2-2-2-3-2.5 1-2.5-1-.6-3z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>',calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4M16 3v4M4 10h16M8 14h2M14 14h2"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',moon:'<path d="M20 15a8 8 0 0 1-11-11 8.5 8.5 0 1 0 11 11z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const TRIGGERS=['Stress','Poor sleep','Skipped meals','Dehydration','Screen time','Heat','Sun glare','Caffeine','Hormonal changes','Exercise','Unwell','Other food'];
const SYMPTOMS=['Light sensitivity','Sound sensitivity','Nausea','Aura','Dizziness','Throbbing','One-sided pain','Neck pain'];
const RELIEF=['Rest','Dark room','Water','Ice pack','Sleep','Relaxation','Medication'];
let entries=[],loadError='',rawBackup=null,storageBlocked=false,lastStored=null;
try{rawBackup=localStorage.getItem(STORAGE_KEY);if(rawBackup) entries=parseBackup(rawBackup);}catch(err){loadError='Your saved diary could not be read. It has been left untouched. Download the original data in Data & settings before making changes.';storageBlocked=true;}
lastStored=rawBackup;
const PAGES=['record','diary','insights','settings'];
let view=PAGES.includes(location.hash.slice(1))?location.hash.slice(1):'record';
let burstListOpen=false;
let quickBursts=[],quickTiming=null,isQuickEntry=false,holdController=null,holdFrame=null;
let filters={search:'',kind:'all',period:'all'},insightDays=30,editing=null,chosenKind='headache',chosenSeverity=null,durationChoice='ongoing',pendingDelete=null,undoEntry=null,toastTimer;
const date=d=>new Intl.DateTimeFormat(undefined,{day:'numeric',month:'short',year:'numeric'}).format(new Date(d));
const time=d=>new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit'}).format(new Date(d));
const exactTime=d=>new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(d));
const burstCount=bursts=>`${bursts.length} ${bursts.length===1?'burst':'bursts'}`;
function burstList(bursts){return `<ol class="burst-times">${bursts.map(b=>`<li><span>${date(b.startedAt)} · ${exactTime(b.startedAt)} – ${date(b.startedAt)!==date(b.endedAt)?date(b.endedAt)+' · ':''}${exactTime(b.endedAt)}</span><strong>${formatHeldTime(durationMs(b))}</strong></li>`).join('')}</ol>`;}
const toLocal=d=>{const x=new Date(d);return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,19)};
const sort=xs=>[...xs].sort((a,b)=>Date.parse(b.startedAt)-Date.parse(a.startedAt));
const ongoing=()=>entries.find(e=>!e.endedAt);
function save(next){if(storageBlocked)throw new Error('Saved data needs attention. Open Data & settings.');if(localStorage.getItem(STORAGE_KEY)!==lastStored)throw new Error('Your diary changed in another tab. Reload this page before saving.');const text=JSON.stringify({schemaVersion:SCHEMA_VERSION,entries:next});localStorage.setItem(STORAGE_KEY,text);lastStored=text;entries=next;}
function toast(message,undo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button id="undo-delete">Undo</button>':''}`;$('#toast').hidden=false;if(undo)$('#undo-delete').onclick=()=>{try{save(mergeEntries(entries,[undoEntry]));undoEntry=null;render();toast('Episode restored.');}catch(e){toast(e.message);}};toastTimer=setTimeout(()=>$('#toast').hidden=true,undo?15000:6000);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const fileDate=()=>new Date().toLocaleDateString('en-CA').replaceAll('/','-');
function exportBackup(){download(`tracking-diary-${fileDate()}.json`,JSON.stringify({schemaVersion:SCHEMA_VERSION,exportedAt:new Date().toISOString(),entries},null,2),'application/json');toast('Backup downloaded. Keep it somewhere private.');}
function exportCSV(list=entries){download(`tracking-diary-${fileDate()}.csv`,toCSV(sort(list)),'text/csv;charset=utf-8');}
function summaryCards(summary){return `<div class="summary-grid"><article class="stat"><div class="stat-top">Episodes recorded<span class="stat-icon">${icon('book')}</span></div><div class="stat-value">${summary.list.length}<small>episodes</small></div><div class="stat-note">Every entry is a useful observation</div></article><article class="stat"><div class="stat-top">Days with a headache<span class="stat-icon">${icon('calendar')}</span></div><div class="stat-value">${summary.days}<small>days</small></div><div class="stat-note">Based on episode start dates</div></article><article class="stat"><div class="stat-top">Average duration<span class="stat-icon">${icon('clock')}</span></div><div class="stat-value">${summary.avgMinutes===null?'—':(summary.avgMinutes===0?'&lt;1m':formatDuration(summary.avgMinutes))}</div><div class="stat-note">${summary.completed.length?'Completed episodes only':'Appears after a completed episode'}</div></article></div>`;}
function episodeDuration(e){const ms=durationMs(e);return ms<60000?`${Math.max(0,ms/1000).toFixed(1)}s`:formatDuration(durationMinutes(e));}
function renderEntry(e){return `<article class="episode" data-entry="${esc(e.id)}"><div class="episode-header"><div class="episode-type-icon">${icon(e.kind==='migraine'?'moon':'spark')}</div><div><h3 class="episode-title">${TYPES.find(t=>t.id===e.kind).label}</h3><p class="episode-time">${date(e.startedAt)} · ${time(e.startedAt)} &nbsp;·&nbsp; ${episodeDuration(e)}${e.bursts?` total pain · ${burstCount(e.bursts)}`:!e.endedAt?' · ongoing':''}</p></div><span class="badge" data-level="${e.severity}">${SEVERITIES[e.severity]}</span></div>${e.bursts?`<details class="burst-details"><summary>Show burst times</summary>${burstList(e.bursts)}</details><div class="print-only">${burstList(e.bursts)}</div>`:''}${e.triggers.length||e.symptoms.length?`<div class="episode-tags">${[...e.triggers,...e.symptoms].map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}${e.relief.length?`<p class="episode-note">Relief: ${esc(e.relief.join(', '))}</p>`:''}${e.medication?`<p class="episode-note">Medication: ${esc(e.medication)}</p>`:''}${e.impact?`<p class="episode-note">Activity: ${esc(e.impact)}</p>`:''}${e.notes?`<p class="episode-note">${esc(e.notes)}</p>`:''}<div class="episode-actions">${!e.endedAt?'<button data-action="finish">End now</button>':''}<button data-action="edit" aria-label="Edit ${esc(e.kind)} from ${date(e.startedAt)}">Edit</button><button data-action="delete" aria-label="Delete ${esc(e.kind)} from ${date(e.startedAt)}">Delete</button></div></article>`;}
function filteredEntries(){const since=filters.period==='all'?0:Date.now()-Number(filters.period)*86400000;return sort(entries.filter(e=>(filters.kind==='all'||e.kind===filters.kind)&&Date.parse(e.startedAt)>=since&&[e.kind,e.notes,e.medication,e.impact,...e.triggers,...e.symptoms,...e.relief].join(' ').toLowerCase().includes(filters.search.toLowerCase())));}
function history(){const list=filteredEntries();return list.length?list.map(renderEntry).join(''):`<div class="empty-state"><div class="empty-icon">${icon('book')}</div><h3>${entries.length?'No matching episodes':'Your diary starts here'}</h3><p>${entries.length?'Try another search or a different filter.':'When a headache comes along, take a moment to log it. You can always add details later.'}</p>${entries.length?'':'<button class="text-button" data-new>Log your first episode →</button>'}</div>`;}
function renderRecord(){const hasBursts=quickBursts.length>0;return `<section class="record-page" aria-labelledby="record-title"><span class="eyebrow">ONE MOMENT AT A TIME</span><h1 id="record-title">Just hold. Then log.</h1><p class="record-intro">Hold for each burst. Add the details when you’re done.</p><div class="record-control"><span class="timer-caption">TOTAL PAIN TIME</span><output id="hold-timer" class="hold-timer" role="timer" aria-label="Total recorded pain duration" aria-live="off">${formatHeldTime(durationMs({bursts:quickBursts}))}</output><button type="button" id="hold-record" class="hold-record" aria-label="Hold to record" aria-describedby="hold-help" ${storageBlocked?'disabled':''}><span class="hold-indicator" aria-hidden="true"></span><span id="hold-label">Hold to record</span><small id="hold-sublabel">Release when it passes</small></button><p id="hold-status" class="hold-status" role="status">${hasBursts?`${burstCount(quickBursts)} recorded. Hold again for the next burst.`:'Ready when you are.'}</p></div>${hasBursts?`<div class="record-draft"><button class="button primary" id="review-recording">Add details & save</button><button class="text-button" id="discard-recording">Discard session</button></div><details class="burst-details draft-bursts" ${burstListOpen?'open':''}><summary>Show ${burstCount(quickBursts)}</summary>${burstList(quickBursts)}</details>`:''}<p id="hold-help" class="hold-help">Press and hold with your finger or mouse.</p><button class="text-button" id="manual-record">Prefer to enter the time yourself? →</button></section>`;}
function bindRecord(){
 const button=$('#hold-record');
 const reset=()=>{cancelAnimationFrame(holdFrame);button.classList.remove('is-recording');button.setAttribute('aria-label','Hold to record');$('#hold-label').textContent='Hold to record';$('#hold-sublabel').textContent='Release when it passes';};
 holdController=createHoldRecorder({button,onStart:start=>{
   button.classList.add('is-recording');button.setAttribute('aria-label','Recording. Release to finish this burst');$('#hold-label').textContent='Release to finish';$('#hold-sublabel').textContent='Recording burst…';$('#hold-status').textContent='Recording this burst. Release to add it.';
   const previous=durationMs({bursts:quickBursts});
   const tick=()=>{if(!button.isConnected)return;$('#hold-timer').textContent=formatHeldTime(previous+Date.now()-start);holdFrame=requestAnimationFrame(tick);};tick();
 },onComplete:captured=>{reset();try{quickBursts=createBurstSession([...quickBursts,captured]).bursts;render();$('#hold-record').focus();}catch(err){$('#hold-status').textContent=err.message;}},onCancel:()=>{reset();if($('#hold-timer'))$('#hold-timer').textContent=formatHeldTime(durationMs({bursts:quickBursts}));if($('#hold-status'))$('#hold-status').textContent=quickBursts.length?`This burst was cancelled. Your ${burstCount(quickBursts)} are still ready to save.`:'Recording cancelled. Hold again when you’re ready.';}});
 $('#manual-record').onclick=()=>openForm(ongoing());
 if($('#review-recording'))$('#review-recording').onclick=()=>openForm(null,createBurstSession(quickBursts));
 if($('#discard-recording'))$('#discard-recording').onclick=()=>{quickBursts=[];burstListOpen=false;render();};
}
function renderDiary(){const s=summarise(entries,Date.now()-30*86400000),active=ongoing();return `<div class="page-heading"><div><span class="eyebrow heading-kicker">YOUR EVERYDAY, A LITTLE CLEARER</span><h1>My diary<span style="color:#9eaf91">.</span></h1><p>A quiet place to notice how you’re feeling.</p></div><button class="button primary" data-new>${icon('plus')} Log episode</button></div>${active?`<div class="ongoing-banner"><span class="pulse"></span><div><strong>${active.kind==='migraine'?'Migraine':'Headache'} in progress</strong><p>Started ${date(active.startedAt)} at ${time(active.startedAt)} · <span id="live-duration">${formatDuration(durationMinutes(active))}</span></p></div><button class="button primary" id="finish-active">End now ${icon('clock')}</button></div>`:''}<p class="section-label"><span class="line"></span> YOUR LAST 30 DAYS</p>${summaryCards(s)}<div class="diary-grid"><section><div class="section-heading"><h2>Recent episodes <small>(${entries.length})</small></h2><button class="text-button" id="export-history" ${!entries.length?'disabled':''}>${icon('download')} Export</button></div><div class="history-filters"><input id="search" type="search" aria-label="Search diary" placeholder="Search notes, triggers…" value="${esc(filters.search)}"><select id="kind-filter" aria-label="Filter episode type"><option value="all">All types</option>${TYPES.map(t=>`<option value="${t.id}" ${filters.kind===t.id?'selected':''}>${t.label}</option>`).join('')}</select><select id="period-filter" aria-label="Filter time period">${[['all','All time'],['30','Last 30 days'],['90','Last 90 days']].map(([v,t])=>`<option value="${v}" ${filters.period===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="history">${history()}</div></section><aside class="diary-aside"><article class="aside-card"><span class="mini-icon">${icon('spark')}</span><h3>Patterns take a little time.</h3><p>Keep a note of the small things — sleep, stress, what helped. Your diary brings those observations together.</p><a class="text-button" href="#insights">Explore your insights ${icon('arrow')}</a></article><article class="aside-card"><span class="eyebrow" style="font-size:9px">A SIMPLE SEVERITY GUIDE</span><div class="scale-row"><span class="severity-dot mild"></span> Mild <span>Normal activity</span></div><div class="scale-row"><span class="severity-dot moderate"></span> Moderate <span>Activity is harder</span></div><div class="scale-row"><span class="severity-dot severe"></span> Severe <span>Activity is prevented</span></div><div class="scale-note">Choose what best describes your experience.</div></article></aside></div>`;}
function bars(items,total){return items.map(([label,count])=>`<div class="bar-row"><span class="bar-label">${esc(label)}</span><div class="bar-track"><div class="bar-fill" style="width:${total?count/total*100:0}%"></div></div><span class="bar-number">${count}</span></div>`).join('');}
function renderInsights(){const s=summarise(entries,Date.now()-insightDays*86400000);return `<div class="page-heading"><div><span class="eyebrow heading-kicker">YOUR OBSERVATIONS, TOGETHER</span><h1>A clearer picture.</h1><p>A simple overview to reflect on or share at an appointment.</p></div><select id="insight-period" class="period-select" aria-label="Insights period">${[30,90,365].map(d=>`<option value="${d}" ${insightDays===d?'selected':''}>Last ${d} days</option>`).join('')}</select></div><p class="section-label"><span class="line"></span> LAST ${insightDays} DAYS · ${date(Date.now())}</p>${summaryCards(s)}${renderInsightCharts(entries,insightDays)}${!s.list.length?`<div class="empty-state"><div class="empty-icon">${icon('chart')}</div><h3>A picture will emerge, one entry at a time.</h3><p>Log an episode to start building your personal overview.</p><button class="text-button" data-new>Log an episode →</button></div>`:`<div class="insights-grid"><article class="content-card"><h3>Severity at a glance</h3><p>Number of episodes at each severity level.</p>${bars([1,2,3].map(n=>[SEVERITIES[n],s.list.filter(e=>e.severity===n).length]),s.list.length)}</article><article class="content-card"><h3>Most noted triggers</h3><p>Possible triggers you recorded alongside episodes.</p>${s.topTriggers.length?bars(s.topTriggers,s.list.length):'<p class="info-note">Add possible triggers to your entries to see them here.</p>'}<div class="info-note">These are observations, not confirmed causes.</div></article></div><article class="content-card"><h3>Bring your diary along.</h3><p>Print a summary and the episodes in this period, or download a spreadsheet-friendly CSV.</p><div class="action-row"><button class="button primary" id="print-summary">Print summary</button><button class="button" id="insights-csv">${icon('download')} Export this period</button></div></article><div class="print-only"><h2>Episode details</h2>${sort(s.list).map(renderEntry).join('')}</div>`}`;}
function renderSettings(){return `<div class="page-heading"><div><span class="eyebrow heading-kicker">YOURS TO KEEP</span><h1>Data & settings.</h1><p>A little care for the things you’ve recorded.</p></div></div><article class="content-card"><h3>${icon('shield')} Private, and on your device.</h3><p>Your diary is stored in this browser on this device. Entries aren’t uploaded to a server or synced across devices. Clearing this browser’s data, using private browsing, or changing the app’s address can make your entries unavailable. Anyone with access to this browser profile may be able to read them.</p><p>Keep a backup regularly, especially before switching devices or browsers.</p><span class="tag">${entries.length} saved episodes</span></article><article class="content-card"><h3>Back up your diary</h3><p>A JSON backup keeps all details and can be imported on another device. CSV is useful for spreadsheets and appointments. These downloads contain your health information.</p><div class="action-row"><button class="button primary" id="backup">${icon('download')} Download backup</button><button class="button" id="csv">Export CSV</button><button class="button" id="import">Import backup</button></div><p class="info-note">Imports merge with existing entries. For matching entries, the most recently updated version is kept.</p></article>${loadError?'<article class="content-card"><h3>Recover original data</h3><p>The saved data failed validation and has not been changed. Download the original file for recovery.</p><button class="button" id="raw-backup">Download original data</button></article>':''}<article class="content-card"><h3>Keep your diary close</h3><p>Add a Tracking Diary icon to your phone’s home screen for quick access.</p><p><strong>Android · Chrome</strong></p><ol class="install-steps"><li>Open this diary in <strong>Chrome</strong>.</li><li>Tap the three-dot menu <strong>⋮</strong>, then <strong>Install and create shortcut</strong>. Depending on your Chrome version, this may be called <strong>Add to home screen</strong> or <strong>Install app</strong>.</li><li>Choose <strong>Install</strong> or <strong>Create shortcut</strong>, if offered, and confirm. The diary icon will appear on your home screen or in your app launcher.</li></ol><p><strong>iPhone / iPad · Safari</strong></p><ol class="install-steps"><li>Open this diary in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong> (the square with an upward arrow), or open <strong>Page Menu → Share</strong>, then <strong>Add to Home Screen</strong>. You may need to scroll through the actions; if it is missing, check <strong>Edit Actions</strong>.</li><li>Keep <strong>Open as Web App</strong> turned on if shown, then tap <strong>Add</strong>.</li></ol><p>Tap the new icon to open your diary. Adding an icon does not back up or sync your entries.</p><p id="offline-status" class="info-note">Checking offline availability…</p></article><article class="content-card"><h3>Room to grow</h3><p>Headaches and migraines are the first tracking category. The record format separates shared timing and metadata from the episode details, so future trackers can be added without replacing your diary.</p><p>The severity guide follows the three levels in the Royal Children’s Hospital diary.</p><a class="source-link" href="https://www.rch.org.au/uploadedfiles/main/content/clinicalguide/headachediary.pdf" target="_blank" rel="noopener noreferrer">View the original headache diary ↗</a><p class="info-note">A personal record for your observations. It doesn’t diagnose conditions or recommend treatment.</p></article>`;}
function bindEntries(){ $$('[data-entry]').forEach(card=>card.onclick=e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;const entry=entries.find(x=>x.id===card.dataset.entry);if(action==='edit')openForm(entry);if(action==='finish')finish(entry);if(action==='delete'){pendingDelete=entry;$('#confirm-dialog').showModal();}}); $$('[data-new]').forEach(b=>b.onclick=()=>openForm(ongoing())); }
function render(){
 const burstDisclosure=$('.draft-bursts');if(burstDisclosure&&quickBursts.length)burstListOpen=burstDisclosure.open;
 if(holdController){holdController.destroy();holdController=null;}cancelAnimationFrame(holdFrame);
 document.title=`${view==='record'?'Record':view==='diary'?'My diary':view==='insights'?'Insights':'Data & settings'} — Tracking Diary`;$$('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===view);a.setAttribute('aria-current',a.dataset.page===view?'page':'false');});$('#today').textContent=new Intl.DateTimeFormat(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());$('#page').innerHTML=`${loadError?`<div class="load-error" role="alert"><p>${esc(loadError)}</p><a href="#settings">Open Data & settings →</a></div>`:''}${view==='record'?renderRecord():view==='diary'?renderDiary():view==='insights'?renderInsights():renderSettings()}`;bindEntries();
 if(view==='record')bindRecord();
 if(view==='diary'){ $('#search').oninput=e=>{filters.search=e.target.value;$('#history').innerHTML=history();bindEntries();};$('#kind-filter').onchange=e=>{filters.kind=e.target.value;render();};$('#period-filter').onchange=e=>{filters.period=e.target.value;render();};$('#export-history').onclick=()=>exportCSV(filteredEntries());if($('#finish-active'))$('#finish-active').onclick=()=>finish(ongoing());}
 if(view==='insights'){ $('#insight-period').onchange=e=>{insightDays=Number(e.target.value);render();};if($('#print-summary'))$('#print-summary').onclick=()=>window.print();if($('#insights-csv'))$('#insights-csv').onclick=()=>exportCSV(summarise(entries,Date.now()-insightDays*86400000).list);}
 if(view==='settings'){ $('#backup').onclick=exportBackup;$('#csv').onclick=()=>exportCSV();$('#import').onclick=()=>$('#import-file').click();if($('#raw-backup'))$('#raw-backup').onclick=()=>download('tracking-diary-original.json',rawBackup??'','application/json');updateOfflineStatus();}
}
function finish(e){if(!e)return;try{const now=new Date().toISOString();save(entries.map(x=>x.id===e.id?validateEntry({...x,endedAt:now,updatedAt:now}):x));render();toast('Episode ended. You can add more details any time.');}catch(err){toast(err.message);}}
function optionChips(id,options,selected=[]){$(id).innerHTML=options.map(t=>`<button type="button" data-value="${esc(t)}" aria-pressed="${selected.includes(t)}">${esc(t)}</button>`).join('');$(id).onclick=e=>{const b=e.target.closest('button');if(b)b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');};}
function setChoice(selector,key,value){$$(selector).forEach(b=>b.setAttribute('aria-pressed',String(b.dataset[key])===String(value)));}
function openForm(e=null,captured=null){if(storageBlocked){toast('Open Data & settings to recover your existing diary.');return;}editing=e||null;quickTiming=captured||(e?.bursts?createBurstSession(e.bursts):null);isQuickEntry=Boolean(captured);$('#entry-dialog').classList.toggle('quick-entry',isQuickEntry);chosenKind=captured?null:(e?.kind||'headache');chosenSeverity=e?.severity??null;durationChoice=(captured||e?.endedAt)?'custom':'ongoing';$('#entry-form').reset();$('#entry-title').textContent=e?'Edit episode':captured?'Finish your log':'Log an episode';$('#save-entry').innerHTML=`${e?'Save changes':'Save episode'} <span>↗</span>`;$('#started-at').value=toLocal(captured?.startedAt||e?.startedAt||Date.now());$('#ended-at').value=toLocal(captured?.endedAt||e?.endedAt||Date.now());$('#end-field').hidden=durationChoice==='ongoing';$('#ended-at').required=durationChoice!=='ongoing';setChoice('[data-kind]','kind',chosenKind);setChoice('[data-severity]','severity',chosenSeverity);setChoice('[data-duration]','duration',durationChoice);$('#form-error').textContent='';$('#timing-hint').textContent='The start time is filled in for you. Adjust it if needed.';optionChips('#trigger-options',TRIGGERS,e?.triggers);optionChips('#symptom-options',SYMPTOMS,e?.symptoms);optionChips('#relief-options',RELIEF,e?.relief);$('#other-trigger').value=e?.triggers.filter(t=>!TRIGGERS.includes(t)).join('; ')||'';$('#impact').value=e?.impact||'';$('#medication').value=e?.medication||'';$('#notes').value=e?.notes||'';$('#more-details').open=Boolean(e&&(e.notes||e.medication||e.impact||e.triggers.length||e.symptoms.length||e.relief.length));const burstSession=Boolean(quickTiming?.bursts);$('#timing-details').hidden=burstSession;$('#timing-details').open=!captured;$('#recorded-timing').hidden=!burstSession;$('#recorded-bursts').hidden=!burstSession;if(burstSession){$('#recorded-timing').textContent=`${burstCount(quickTiming.bursts)} · ${formatHeldTime(durationMs(quickTiming))} total pain time`;$('#recorded-bursts').open=false;$('#recorded-burst-list').innerHTML=burstList(quickTiming.bursts);}$('#entry-dialog').showModal();}
$('#kind-options').onclick=e=>{const b=e.target.closest('button');if(b){chosenKind=b.dataset.kind;setChoice('[data-kind]','kind',chosenKind);}};
$('#severity-options').onclick=e=>{const b=e.target.closest('button');if(b){chosenSeverity=Number(b.dataset.severity);setChoice('[data-severity]','severity',chosenSeverity);}};
$('#duration-options').onclick=e=>{quickTiming=null;const b=e.target.closest('button');if(!b)return;durationChoice=b.dataset.duration;setChoice('[data-duration]','duration',durationChoice);$('#end-field').hidden=durationChoice==='ongoing';$('#ended-at').required=durationChoice!=='ongoing';if(!['ongoing','custom'].includes(durationChoice)){const mins=Number(durationChoice);if(editing){$('#ended-at').value=toLocal(new Date($('#started-at').value).getTime()+mins*60000);$('#timing-hint').textContent='Duration sets the end time from your episode’s start.';}else{$('#ended-at').value=toLocal(Date.now());$('#started-at').value=toLocal(Date.now()-mins*60000);$('#timing-hint').textContent='Quick duration logs a completed episode ending now.';}}};
$('#started-at').oninput=$('#ended-at').oninput=()=>{quickTiming=null;};
$('#start-now').onclick=()=>{quickTiming=null;$('#started-at').value=toLocal(Date.now());};
$('#close-dialog').onclick=()=>$('#entry-dialog').close();
$('#entry-form').onsubmit=e=>{e.preventDefault();try{if(!chosenKind)throw new Error('Choose headache or migraine to continue.');if(!chosenSeverity)throw new Error('Choose a severity level to continue.');const values=id=>$$(id+' button[aria-pressed="true"]').map(b=>b.dataset.value);const now=new Date().toISOString();const other=$('#other-trigger').value.trim();const record=validateEntry({id:editing?.id||crypto.randomUUID(),trackerType:'headache',kind:chosenKind,severity:chosenSeverity,...(quickTiming?.bursts?{bursts:quickTiming.bursts}:{}),startedAt:quickTiming?.startedAt||new Date($('#started-at').value).toISOString(),endedAt:quickTiming?.endedAt||(durationChoice==='ongoing'?null:new Date($('#ended-at').value).toISOString()),triggers:[...new Set([...values('#trigger-options'),...(other?other.split(';').map(x=>x.trim()).filter(Boolean):[])])],symptoms:values('#symptom-options'),relief:values('#relief-options'),medication:$('#medication').value.trim(),impact:$('#impact').value,notes:$('#notes').value.trim(),createdAt:editing?.createdAt||now,updatedAt:now});if(!record.endedAt&&entries.some(x=>!x.endedAt&&x.id!==record.id))throw new Error('End your ongoing episode before starting another.');save([...entries.filter(x=>x.id!==record.id),record]);if(isQuickEntry){burstListOpen=false;quickBursts=[];quickTiming=null;isQuickEntry=false;}$('#entry-dialog').close();render();toast(editing?'Changes saved.':'Episode saved. A little less to remember.');}catch(err){$('#form-error').textContent=err.name==='QuotaExceededError'?'This browser is out of storage. Download a backup in Data & settings.':err.message;}};
$('#cancel-delete').onclick=()=>$('#confirm-dialog').close();$('#confirm-delete').onclick=()=>{try{save(entries.filter(e=>e.id!==pendingDelete.id));undoEntry=pendingDelete;pendingDelete=null;$('#confirm-dialog').close();render();toast('Episode deleted.',true);}catch(e){toast(e.message);}};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Please choose a backup smaller than 10 MB.');const imported=parseBackup(await file.text());save(mergeEntries(entries,imported));render();toast(`Backup imported. ${entries.length} episodes in your diary.`);}catch(err){toast(`Import failed: ${err.message}`);}finally{e.target.value='';}};
window.addEventListener('hashchange',()=>{view=PAGES.includes(location.hash.slice(1))?location.hash.slice(1):'record';render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY||e.key===null){try{const updated=localStorage.getItem(STORAGE_KEY);entries=updated?parseBackup(updated):[];lastStored=updated;const wasEditing=$('#entry-dialog').open;$('#entry-dialog').close();$('#confirm-dialog').close();render();if(wasEditing)toast('Diary changed in another tab. Reopen the episode to edit the latest version.');}catch{storageBlocked=true;loadError='A change from another tab could not be read. Reload this page to recover the saved data.';render();}}});
setInterval(()=>{const a=ongoing();if(a&&$('#live-duration'))$('#live-duration').textContent=formatDuration(durationMinutes(a));},30000);
let offlineReady=false;
function updateOfflineStatus(){if($('#offline-status'))$('#offline-status').textContent=offlineReady?'Offline app shell ready on this browser.':'Offline availability depends on this browser and the hosting environment. Keep a bookmark and a backup.';}
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;updateOfflineStatus();}).catch(()=>updateOfflineStatus());}
render();
